{"function": "() => {
    const article = document.querySelector('article');
    if (!article) return 'No article found';

    const text = article.innerText;
    const lowerText = text.toLowerCase();

    const plasmonIndices = [];
    const plasmonicsIndices = [];

    // Find all occurrences
    let index = lowerText.indexOf('plasmon');
    while (index !== -1) {
        plasmonIndices.push(index);
        index = lowerText.indexOf('plasmon', index + 1);
    }

    index = lowerText.indexOf('plasmonics');
    while (index !== -1) {
        plasmonicsIndices.push(index);
        index = lowerText.indexOf('plasmonics', index + 1);
    }

    // Get context for each occurrence
    const plasmonContexts = plasmonIndices.map(idx => {
        const start = Math.max(0, idx - 100);
        const end = Math.min(text.length, idx + 100);
        return {
            position: idx,
            context: text.substring(start, end),
            fullWord: text.substring(idx, idx + 'plasmon'.length)
        };
    });

    const plasmonicsContexts = plasmonicsIndices.map(idx => {
        const start = Math.max(0, idx - 100);
        const end = Math.min(text.length, idx + 100);
        return {
            position: idx,
            context: text.substring(start, end),
            fullWord: text.substring(idx, idx + 'plasmonics'.length)
        };
    });

    return {
        totalPlasmon: plasmonIndices.length,
        totalPlasmonics: plasmonicsIndices.length,
        plasmonContexts,
        plasmonicsContexts,
        articleLength: text.length
    };
}"}

