{"function": "() => {
    const bodyText = document.body.innerText;
    const lowerText = bodyText.toLowerCase();

    // Search for plasmon/plasmonics
    const plasmonMatches = [];
    const plasmonicsMatches = [];

    const plasmonRegex = /plasmon/gi;
    const plasmonicsRegex = /plasmonics/gi;

    let match;
    while ((match = plasmonRegex.exec(bodyText)) !== null) {
        const start = Math.max(0, match.index - 100);
        const end = Math.min(bodyText.length, match.index + 100);
        plasmonMatches.push({
            word: match[0],
            context: bodyText.substring(start, end),
            index: match.index
        });
    }

    while ((match = plasmonicsRegex.exec(bodyText)) !== null) {
        const start = Math.max(0, match.index - 100);
        const end = Math.min(bodyText.length, match.index + 100);
        plasmonicsMatches.push({
            word: match[0],
            context: bodyText.substring(start, end),
            index: match.index
        });
    }

    // Also check the visible text content
    const mainContent = document.querySelector('main') || document.body;
    const visibleText = mainContent.innerText;
    const hasPlasmon = /plasmon/i.test(visibleText);
    const hasPlasmonics = /plasmonics/i.test(visibleText);

    return {
        totalPlasmon: plasmonMatches.length,
        totalPlasmonics: plasmonicsMatches.length,
        plasmonMatches,
        plasmonicsMatches,
        hasPlasmon,
        hasPlasmonics,
        bodyTextLength: bodyText.length,
        visibleTextLength: visibleText.length
    };
}"}

