{"function": "() => {
    // Get the main article content (excluding citations and related articles)
    const mainContent = document.querySelector('main');
    if (!mainContent) return 'No main content found';

    // Try to get just the article text, not citations
    const articleText = mainContent.innerText;

    // Look for plasmon/plasmonics in the article
    const plasmonRegex = /plasmon/gi;
    const plasmonicsRegex = /plasmonics/gi;

    const plasmonMatches = [];
    const plasmonicsMatches = [];

    let match;
    while ((match = plasmonRegex.exec(articleText)) !== null) {
        const start = Math.max(0, match.index - 150);
        const end = Math.min(articleText.length, match.index + 150);
        plasmonMatches.push({
            word: match[0],
            context: articleText.substring(start, end),
            index: match.index,
            section: getSectionAtPosition(articleText, match.index)
        });
    }

    while ((match = plasmonicsRegex.exec(articleText)) !== null) {
        const start = Math.max(0, match.index - 150);
        const end = Math.min(articleText.length, match.index + 150);
        plasmonicsMatches.push({
            word: match[0],
            context: articleText.substring(start, end),
            index: match.index,
            section: getSectionAtPosition(articleText, match.index)
        });
    }

    // Helper function to determine section
    function getSectionAtPosition(text, pos) {
        const sections = [
            {name: 'Abstract', pattern: /abstract/i},
            {name: 'Introduction', pattern: /introduction/i},
            {name: 'Results', pattern: /results/i},
            {name: 'Discussion', pattern: /discussion/i},
            {name: 'Methods', pattern: /methods/i},
            {name: 'References', pattern: /references/i},
            {name: 'Acknowledgements', pattern: /acknowledgements/i},
            {name: 'Cited by', pattern: /cited by|this article is cited by/i}
        ];

        const precedingText = text.substring(0, pos);
        for (const section of sections) {
            const match = precedingText.match(section.pattern);
            if (match) {
                // Check if this is the last occurrence before position
                const lastIndex = precedingText.lastIndexOf(match[0]);
                if (lastIndex > -1) {
                    return section.name;
                }
            }
        }
        return 'Unknown';
    }

    return {
        articleLength: articleText.length,
        totalPlasmon: plasmonMatches.length,
        totalPlasmonics: plasmonicsMatches.length,
        plasmonMatches,
        plasmonicsMatches,
        hasPlasmon: plasmonMatches.length > 0,
        hasPlasmonics: plasmonicsMatches.length > 0
    };
}"}

